// Kruskal's MST using DSU
// edges: array of [weight, u, v]
// n: number of nodes (0-indexed)
function kruskalMST(n, edges) {
  // DSU
  const parent = Array.from({ length: n }, (_, i) => i);
  const rank = new Array(n).fill(0);

  function find(x) {
    if (parent[x] !== x) parent[x] = find(parent[x]); // path compression
    return parent[x];
  }

  function union(x, y) {
    const px = find(x), py = find(y);
    if (px === py) return false; // already connected - would create cycle
    if (rank[px] < rank[py]) parent[px] = py;
    else if (rank[px] > rank[py]) parent[py] = px;
    else { parent[py] = px; rank[px]++; }
    return true;
  }

  // sort edges by weight ascending
  edges.sort((a, b) => a[0] - b[0]);

  let totalCost = 0;
  let edgesUsed = 0;

  for (const [w, u, v] of edges) {
    if (union(u, v)) { // no cycle - add to MST
      totalCost += w;
      edgesUsed++;
      if (edgesUsed === n - 1) break; // MST complete
    }
  }

  // if edgesUsed < n-1, graph was disconnected (no MST)
  return edgesUsed === n - 1 ? totalCost : -1;
}
